<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['transaction_id']??null,FILTER_VALIDATE_INT);$reason=trim((string)($_POST['reason']??''));if(!$id||$reason===''||strlen($reason)>200){$_SESSION['error']='Provide a valid transaction and a short reversal reason.';header('Location: ../?page=fees');exit;}
$pdo=db();try{$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT * FROM fee_ledger WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$original=$stmt->fetch();if(!$original||$original['reverses_id']||$original['reversal_reason'])throw new DomainException('This entry cannot be reversed.');$prior=$pdo->prepare('SELECT id FROM fee_ledger WHERE reverses_id=:id');$prior->execute(['id'=>$id]);if($prior->fetch())throw new DomainException('This entry has already been reversed.');$value=(float)$original['amount'];$reverseAmount=$original['transaction_type']==='Payment'?$value:-$value;$desc='Reversal: '.$original['description'];if(strlen($desc)>180)$desc=substr($desc,0,180);$ins=$pdo->prepare("INSERT INTO fee_ledger (student_id,term_id,category_id,transaction_type,description,amount,currency,transaction_date,recorded_by,reverses_id,reversal_reason) VALUES (:student,:term,:category,'Adjustment',:description,:amount,:currency,CURDATE(),:user,:original,:reason)");$ins->execute(['student'=>$original['student_id'],'term'=>$original['term_id'],'category'=>$original['category_id'],'description'=>$desc,'amount'=>number_format($reverseAmount,2,'.',''),'currency'=>$original['currency'],'user'=>$user['id'],'original'=>$id,'reason'=>$reason]);$new=(int)$pdo->lastInsertId();audit_log('fees.transaction_reversed','fee_ledger',$id,['reversal_id'=>$new,'reason'=>$reason]);$pdo->commit();$_SESSION['notice']='A reversing ledger entry was posted; the original record remains available.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Fee reversal failed: '.$e->getMessage());$_SESSION['error']='Could not reverse this transaction.';}
header('Location: ../?page=fees&tab=transactions');exit;
